"""Authored bug-fix seeds. Every entry is EXECUTED by kverify before admission:
the repro must show the error and the fixed version must run clean. Entries that fail are dropped."""

PY = ["python3"]


def B(key, lang, title, error, cause, fix, repro, fixed, *, pitfalls=None, versions="", fw=None, tags=None):
    return dict(key=key, lang=lang, title=title, error=error, root_cause=cause, fix=fix, pitfalls=pitfalls or [],
                version_spec=versions, frameworks=fw or [], tags=tags or [], repro=repro, fixed=fixed)


def py(code, contains=None, **kw): return dict(files={"main.py": code}, cmd=PY + ["main.py"], contains=contains, **kw)
def node(code, name="main.js", contains=None, **kw): return dict(files={name: code}, cmd=["node", name], contains=contains, **kw)
def go(code, contains=None, **kw): return dict(files={"main.go": code}, cmd=["go", "run", "main.go"], contains=contains, **kw)
def sh(code, contains=None, **kw): return dict(files={"run.sh": code}, cmd=["bash", "run.sh"], contains=contains, **kw)


